svg.script:

const staticText = document.getElementById('static-text');
const typingText = document.getElementById('typing-text');
const cursor = document.getElementById('cursor');
const lines = [
  "Discord Bot Developer",
  "Bale Bot Developer",
  "Telegram Bot Developer",
  "Frontend Programmer",
  "Backend Developer",
  "Passionate about Development ♥"
];
let currentLine = -1; // Start with welcome text
let currentChar = 0;
let isTyping = true;
let welcomeText = "Welcome to My GitHub Profile!";

function updateText() {
  if (currentLine === -1) {
    // Typing welcome text
    if (currentChar <= welcomeText.length) {
      typingText.textContent = welcomeText.slice(0, currentChar);
      cursor.setAttribute('x', 10 + typingText.getComputedTextLength());
      currentChar++;
      setTimeout(updateText, 100);
    } else {
      // Welcome text done, move to next lines
      staticText.textContent = welcomeText;
      typingText.textContent = "";
      currentLine = 0;
      currentChar = 0;
      setTimeout(updateText, 1000); // Pause before next line
    }
  } else {
    // Typing or deleting other lines
    const text = lines[currentLine];
    if (isTyping) {
      if (currentChar <= text.length) {
        typingText.textContent = text.slice(0, currentChar);
        cursor.setAttribute('x', 10 + staticText.getComputedTextLength() + typingText.getComputedTextLength());
        currentChar++;
        setTimeout(updateText, 100);
      } else {
        isTyping = false;
        setTimeout(updateText, 1000); // Pause before deleting
      }
    } else {
      if (currentChar >= 0) {
        typingText.textContent = text.slice(0, currentChar);
        cursor.setAttribute('x', 10 + staticText.getComputedTextLength() + typingText.getComputedTextLength());
        currentChar--;
        setTimeout(updateText, 50);
      } else {
        isTyping = true;
        currentLine = (currentLine + 1) % lines.length;
        setTimeout(updateText, 500); // Pause before next line
      }
    }
  }
}

updateText();
// Blink cursor
setInterval(() => {
  cursor.style.visibility = cursor.style.visibility === 'hidden' ? 'visible' : 'hidden';
}, 500);
